26	pub fn bytes_repr(b: &[u8]) -> String {
27	    let q = if b.contains(&b'\'') && !b.contains(&b'"') { '"' } else { '\'' };
28	    let mut out = String::from("b");
29	    out.push(q);
30	    for &c in b {
31	        match c {
32	            b'\\' => out.push_str("\\\\"),
33	            b'\t' => out.push_str("\\t"),
34	            b'\n' => out.push_str("\\n"),
35	            b'\r' => out.push_str("\\r"),
36	            _ if c as char == q => {
37	                out.push('\\');
38	                out.push(q);
39	            }
40	            32..=126 => out.push(c as char),
41	            _ => out.push_str(&format!("\\x{c:02x}")),
42	        }
43	    }
44	    out.push(q);
45	    out
46	}
