52	fn find_sub(h: &[u8], n: &[u8], from: usize) -> Option<usize> {
53	    if n.is_empty() {
54	        return (from <= h.len()).then_some(from);
55	    }
56	    if n.len() > h.len() {
57	        return None;
58	    }
59	    (from..=h.len() - n.len()).find(|&i| &h[i..i + n.len()] == n)
60	}
