62	// A bytes argument of a bytes method: bytes, or an int byte where CPython takes one (find, count, in).
63	fn sub_arg(v: &V, m: &str, int_ok: bool) -> Result<Vec<u8>, E> {
64	    if let Some(b) = bytes_of(v) {
65	        return Ok(b);
66	    }
67	    if int_ok {
68	        if let V::Int(i) = v {
69	            if !(0..256).contains(i) {
70	                return val_err("byte must be in range(0, 256)".into());
71	            }
72	            return Ok(vec![*i as u8]);
73	        }
74	    }
75	    let _ = m;
76	    type_err(format!("a bytes-like object is required, not '{}'", tn(v)))
77	}
