80	fn sub_range(a: &Args, at: usize, n: usize) -> Result<(usize, usize), E> {
81	    let get = |k: usize, d: i64| -> Result<i64, E> {
82	        match a.p.get(k) {
83	            None | Some(V::None) => Ok(d),
84	            Some(x) => idx_of(x),
85	        }
86	    };
87	    let n = n as i64;
88	    let fix = |x: i64| if x < 0 { (x + n).max(0) } else { x.min(n) };
89	    Ok((fix(get(at, 0)?) as usize, fix(get(at + 1, n)?) as usize))
90	}
